+/** Variance per item between two days (inclusive): theoretical use from sales vs actual consumption. */
+export function varianceReport(store, from, to) {
+  const theo = new Map();
+  const actual = new Map();
+  for (const s of store.data.sales ?? []) {
+    const day = s.soldAt.slice(0, 10);
+    if (day < from || day > to) continue;
+    for (const n of scaled(getRecipe(store, getDish(store, s.dishId).recipeId), s.qty))
+      theo.set(n.itemId, (theo.get(n.itemId) ?? 0) + n.qty);
+  }
+  for (const m of store.data.movements) {
+    if (m.type !== "consume") continue;
+    const day = m.at.slice(0, 10);
+    if (day < from || day > to) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (batch) actual.set(batch.itemId, (actual.get(batch.itemId) ?? 0) + m.qty);
+  }
+  const r3 = (x) => Math.round(x * 1000) / 1000;
+  return [...new Set([...theo.keys(), ...actual.keys()])]
+    .sort((a, b) => a - b)
+    .map((itemId) => {
+      const t = r3(theo.get(itemId) ?? 0);
+      const a = r3(actual.get(itemId) ?? 0);
+      return { itemId, theoretical: t, actual: a, difference: r3(a - t) };
+    })
+    .filter((l) => l.theoretical > 0 || l.actual > 0);
+}
